(()=>{const dialog=document.querySelector('.graphics-preview');if(!dialog)return;const image=dialog.querySelector('[data-graphics-image]'),pdf=dialog.querySelector('[data-graphics-pdf]'),prev=dialog.querySelector('[data-graphics-prev]'),next=dialog.querySelector('[data-graphics-next]');let files=[],index=0,trigger=null,title='';function render(){const file=files[index],isPdf=/\.pdf(?:$|[?#])/i.test(file);image.hidden=isPdf;pdf.hidden=!isPdf;if(isPdf){image.removeAttribute('src');pdf.src=file;}else{pdf.removeAttribute('src');image.src=file;image.alt=title+' — image '+(index+1);}dialog.querySelector('[data-graphics-count]').textContent=files.length>1?(index+1)+' / '+files.length:'';prev.hidden=next.hidden=files.length<2;prev.disabled=index===0;next.disabled=index===files.length-1;dialog.querySelector('[data-graphics-open]').href=file;}document.querySelectorAll('[data-graphic-preview]').forEach(card=>card.addEventListener('click',event=>{event.preventDefault();files=JSON.parse(card.dataset.graphicPreview);index=0;trigger=card;title=card.dataset.graphicTitle;dialog.querySelector('#graphics-preview-title').textContent=title;render();dialog.showModal();document.body.classList.add('graphics-preview-open');}));prev.addEventListener('click',()=>{if(index>0){index--;render();}});next.addEventListener('click',()=>{if(index<files.length-1){index++;render();}});dialog.querySelector('[data-graphics-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientY<r.top)dialog.close();}});dialog.addEventListener('close',()=>{document.body.classList.remove('graphics-preview-open');pdf.removeAttribute('src');image.removeAttribute('src');trigger?.focus();});})();
